import jakarta.validation.constraints.*;
import jakarta.ws.rs.core.*;
import jakarta.transaction.Transactional;
import java.util.*;
record CreateOrder(@NotBlank(message="itemは必須です") String item,@Min(value=1,message="countは1以上です") int count){} record OrderDto(long id,String item,int count){} record ApiError(String code,Object detail){}
class OrderService{private final Map<String,Integer> stock=new HashMap<>(Map.of("book",3,"pen",1));@Transactional Response create(CreateOrder in){List<String> errors=MiniValidator.validate(in);if(!errors.isEmpty())return Response.status(400).entity(new ApiError("VALIDATION_ERROR",errors)).build();Integer current=stock.get(in.item());if(current==null)return Response.status(404).entity(new ApiError("NOT_FOUND","商品がありません")).build();if(current<in.count())return Response.status(409).entity(new ApiError("OUT_OF_STOCK","在庫が足りません")).build();stock.put(in.item(),current-in.count());return Response.status(201).entity(new OrderDto(1,in.item(),in.count())).build();}}
public class FinalOrderApi{public static void main(String[]a){Scanner s=new Scanner(System.in);String item=s.next();if(item.equals("_"))item="";CreateOrder in=new CreateOrder(item,s.nextInt());Response r=new OrderService().create(in);System.out.println(r.getStatus()+" "+r.getEntity());}}

